const weatherTypes  =  ['晴', '多云', '小雨', '大雨', '阴'];

const GetWeathericon  =  (type) => {
    const icons  =  {
        '晴':  '☀️',
        '多云':  '☁️',
        '小雨':  '🌧️',
        '大雨':  '⛈️',
        '阴':  '🌫️'
    };
    return icons[type] || '☀️';
};

const Generatemockweather  =  (lat, lng) => {
    const seed  =  Math.abs(Math.round(lat  *  1000  +  lng  *  100));
    const typeIdx  =  seed  %  weatherTypes.length;
    const temp  =  15  +  (seed  %  20);
    const rainProb  =  (seed  %  100);
    const type  =  weatherTypes[typeIdx];

    return {
        type:  type,
        icon:  GetWeathericon(type),
        temperature:  temp,
        rainProbability:  rainProb
    };
};

export { Generatemockweather, GetWeathericon };
